def choose_move(observation):
    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pair(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except:
            pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp(dst[0] - src[0]), clamp(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp(src[0] - dst[0]), clamp(src[1] - dst[1])]

    def is_xy(v):
        return isinstance(v, (list, tuple)) and len(v) >= 2

    def extract_points(x):
        pts = []
        if isinstance(x, dict):
            for k in ("positions", "cells", "targets", "resources", "resource_positions", "unclaimed_cells",
                      "opponent_territory", "territory_targets", "blocked_cells", "hazards", "walls"):
                if k in x:
                    pts.extend(extract_points(x.get(k)))
            if "position" in x:
                p = pair(x.get("position"), None)
                if p is not None:
                    pts.append(p)
            return pts
        if isinstance(x, (list, tuple)):
            for it in x:
                if is_xy(it):
                    pts.append(pair(it))
                elif isinstance(it, dict):
                    pts.extend(extract_points(it))
        return pts

    def best_by_distance(src, pts, want_min=True):
        best = None
        best_d = None
        for p in pts:
            d = manhattan(src, p)
            if best is None or (want_min and d < best_d) or ((not want_min) and d > best_d):
                best, best_d = p, d
        return best

    def nearest(src, pts):
        return best_by_distance(src, pts, True)

    def farthest(src, pts):
        return best_by_distance(src, pts, False)

    env = observation.get("environment_name", "") or ""
    sx, sy = pair(observation.get("self_position"), (0, 0))
    ox, oy = pair(observation.get("opponent_position"), (sx, sy))
    me = (sx, sy)
    opp = (ox, oy)

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    maxx = gw - 1 if gw > 0 else 0
    maxy = gh - 1 if gh > 0 else 0

    obstacles = []
    for key in ("walls", "blocked_cells", "obstacles", "hazards"):
        obstacles.extend(extract_points(observation.get(key)))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer") or "pursuer"
        if role == "pursuer":
            return step_toward(me, opp)

        corners = [(0, 0), (0, maxy), (maxx, 0), (maxx, maxy)]
        target = farthest(opp, corners)
        if target is None:
            target = (maxx, maxy)
        move = step_toward(me, target)
        if move == [0, 0]:
            move = step_away(me, opp)
        return move

    if env == "territory_control":
        targets = []
        for key in ("unclaimed_cells", "opponent_territory", "territory_targets", "frontier", "capture_cells"):
            targets.extend(extract_points(observation.get(key)))
        if not targets:
            grid = observation.get("grid")
            if isinstance(grid, (list, tuple)):
                for y, row in enumerate(grid):
                    if isinstance(row, (list, tuple)):
                        for x, cell in enumerate(row):
                            if cell in (0, ".", None):
                                targets.append((x, y))
        target = nearest(me, targets)
        if target is not None:
            return step_toward(me, target)
        if is_xy(observation.get("objective_position")):
            return step_toward(me, pair(observation.get("objective_position")))
        return step_toward(me, opp) if opp != me else [0, 0]

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "targets", "collectibles"):
        resources.extend(extract_points(observation.get(key)))

    if resources:
        target = nearest(me, resources)
        return step_toward(me, target)

    if is_xy(observation.get("resource_position")):
        return step_toward(me, pair(observation.get("resource_position")))

    # General fallback: in resource collection move to any visible goal; otherwise be mildly aggressive.
    if env == "resource_collection" or env == "":
        goals = []
        for key in ("goal_positions", "food", "items"):
            goals.extend(extract_points(observation.get(key)))
        target = nearest(me, goals)
        if target is not None:
            return step_toward(me, target)

    if opp != me:
        return step_toward(me, opp)
    return [0, 0]

